// Consejo de 3 LLMs distintas que evaluan si la respuesta esta fundamentada en los pasajes.
const body = $input.first().json.body || {};
const pregunta = body.pregunta || '';
const respuesta = body.respuesta || '';
const contexto = body.contexto || '';

const MODELS = [
  'anthropic/claude-sonnet-4',
  'openai/gpt-4o',
  'meta-llama/llama-3.3-70b-instruct',
];

const systemPrompt = `Eres un evaluador estricto de respuestas RAG. Recibes una pregunta del usuario, los pasajes recuperados de sus fuentes, y la respuesta que dio otra LLM.

Tu trabajo: determinar si la respuesta cumple los principios de CoWorkerIA:
1. NUNCA INVENTA: cada afirmacion factual de la respuesta debe estar sustentada por los pasajes.
2. SIEMPRE CITA: las citas [archivo, pag. N] deben apuntar al pasaje correcto.
3. NO OMITE INFO CRITICA de los pasajes que responda directamente la pregunta.

Devuelve EXCLUSIVAMENTE un JSON con esta estructura exacta:
{
  "fundamentada": true|false,
  "score": 1|2|3|4|5,
  "problemas": ["descripcion corta de cada problema detectado, o array vacio"],
  "razonamiento": "explicacion breve de tu veredicto en 1-2 frases"
}

No agregues texto fuera del JSON.`;

const userPrompt = `PREGUNTA DEL USUARIO:\n${pregunta}\n\nPASAJES RECUPERADOS (fuente de verdad):\n${contexto}\n\nRESPUESTA A EVALUAR:\n${respuesta}`;

async function callJudge(model) {
  const t0 = Date.now();
  try {
    const data = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: {
        'Authorization': `Bearer ${$env.OPENROUTER_API_KEY}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'http://localhost',
        'X-Title': 'CoWorkerIA Council',
      },
      body: {
        model,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt },
        ],
        max_tokens: 1500,
        temperature: 0,
      },
      json: true,
    });
    const ms = Date.now() - t0;
    const raw = data.choices?.[0]?.message?.content || '{}';
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      // Limpiar code fences markdown + extraer primer JSON balanceado
      const cleaned = raw.replace(/^```(?:json)?\s*/gm, '').replace(/```\s*$/gm, '').trim();
      try {
        parsed = JSON.parse(cleaned);
      } catch (e2) {
        // Buscar JSON balanceado en el texto
        let depth = 0, start = -1, found = null;
        for (let i = 0; i < cleaned.length; i++) {
          if (cleaned[i] === '{') { if (depth === 0) start = i; depth++; }
          else if (cleaned[i] === '}') { depth--; if (depth === 0 && start !== -1) { found = cleaned.slice(start, i + 1); break; } }
        }
        if (found) {
          try { parsed = JSON.parse(found); }
          catch { parsed = { error: 'JSON balanceado invalido', raw_preview: cleaned.slice(0, 300) }; }
        } else {
          parsed = { error: 'No se hallo JSON', raw_preview: cleaned.slice(0, 300) };
        }
      }
    }
    return { juez: model, ms, ...parsed };
  } catch (e) {
    return { juez: model, error: (e?.message || String(e)).slice(0,200), ms: Date.now() - t0 };
  }
}

// IMPORTANTE: bindeamos this para que callJudge tenga acceso a this.helpers
const boundCall = callJudge.bind(this);
const votos = await Promise.all(MODELS.map(boundCall));

const validos = votos.filter(v => typeof v.fundamentada === 'boolean');
const totalEvaluado = validos.length;
const fundamentadaCount = validos.filter(v => v.fundamentada === true).length;
const scores = validos.map(v => typeof v.score === 'number' ? v.score : 3);
const scorePromedio = scores.length ? scores.reduce((a,b)=>a+b,0)/scores.length : 0;

let veredicto;
if (totalEvaluado === 0) veredicto = 'sin_consenso_jueces_fallaron';
else if (fundamentadaCount === totalEvaluado) veredicto = 'consenso_fundamentada';
else if (fundamentadaCount === 0) veredicto = 'consenso_no_fundamentada';
else if (fundamentadaCount >= totalEvaluado / 2) veredicto = 'mayoria_a_favor';
else veredicto = 'mayoria_en_contra';

const problemasSet = new Set();
for (const v of validos) {
  if (Array.isArray(v.problemas)) v.problemas.forEach(p => p && problemasSet.add(p));
}

return [{ json: {
  veredicto,
  score_promedio: Number(scorePromedio.toFixed(2)),
  fundamentada_votos: `${fundamentadaCount}/${totalEvaluado}`,
  problemas_detectados: Array.from(problemasSet),
  votos,
}}];
